const sets={
  default:[['Rift 01','Zapatilla lifestyle','$128','product-sneaker.png'],['Mono Bomber','Chaqueta oversized','$142','editorial-woman.png'],['North Shell','Chaqueta técnica','$168','campaign-men.png'],['Pulse Mini','Zapatilla kids','$74','campaign-kids.png']],
  men:[['North Shell','Chaqueta técnica','$168','campaign-men.png'],['Form Cargo','Pantalón amplio','$96','campaign-men.png'],['Rift 01','Zapatilla lifestyle','$128','product-sneaker.png'],['Mono Cap','Gorra estructurada','$38','campaign-accessories.png']],
  women:[['Mono Bomber','Chaqueta oversized','$142','editorial-woman.png'],['Studio Wide','Pantalón fluido','$88','editorial-woman.png'],['Rift 01 Pearl','Zapatilla lifestyle','$128','product-sneaker.png'],['Form Mini Bag','Bolso técnico','$64','campaign-accessories.png']],
  kids:[['Play Shell','Chaqueta color block','$64','campaign-kids.png'],['Move Set','Conjunto cómodo','$72','campaign-kids.png'],['Pulse Mini','Zapatilla kids','$74','campaign-kids.png'],['Color Crew','Sudadera suave','$46','campaign-kids.png']],
  sale:[['Rift 01 Archive','Antes $128','$89','product-sneaker.png'],['Mono Bomber','Antes $142','$99','editorial-woman.png'],['North Shell','Antes $168','$118','campaign-men.png'],['Form Audio','Antes $90','$59','campaign-accessories.png']]
};
const grid=document.querySelector('[data-products]');if(grid){const key=grid.dataset.products||'default';grid.innerHTML=sets[key].map((p,i)=>`<article class="product"><div class="product-media"><img src="assets/${p[3]}?v=325854a" alt="${p[0]}"><span class="pill">${i===0?'NUEVO':'RITMO SELECT'}</span><button class="heart" aria-label="Guardar ${p[0]}" style="border:0;background:none">♡</button></div><h3>${p[0]}</h3><p>${p[1]} <span class="color-swatch"></span></p><strong>${p[2]}</strong></article>`).join('');document.querySelectorAll('.heart').forEach(btn=>btn.addEventListener('click',()=>{const t=document.querySelector('.toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}));}
